private (double Value, string Symbol) GetLargestWholeNumber()
{
    // Use absolute Bits to avoid recomputing derived units unnecessarily.
    // Compare against bits thresholds directly (single field, no division).
    long absBits = Math.Abs(Bits);

    if (absBits >= BitsInByte * BytesInTerabyte) return (Terabytes, TerabyteSymbol);
