/// <summary>
/// Returns a formatted string representation of this data size.
/// </summary>
/// <param name="format">A standard or custom numeric format string.</param>
/// <param name="provider">An object that supplies culture-specific formatting information.</param>
/// <returns>A formatted string representing this data size.</returns>
public string ToString(string? format, IFormatProvider? formatProvider = null)
{
    format ??= "0.## ";
    formatProvider ??= CultureInfo.CurrentCulture;

    if (!format.Contains('#') && !format.Contains('0'))
    {
        format = "0.## " + format;
    }

    if (format.Contains("#.##", StringComparison.Ordinal))
    {
        format = format.Replace("#.##", "0.##");
    }

    // Check for explicit unit symbols using ordinal comparison to avoid
    // culture-aware searches and redundant string.Replace allocations
    // (the symbols are already the canonical values).
    if (format.Contains(TerabyteSymbol, StringComparison.Ordinal))
        return Terabytes.ToString(format, formatProvider);

    if (format.Contains(GigabyteSymbol, StringComparison.Ordinal))
        return Gigabytes.ToString(format, formatProvider);

    if (format.Contains(MegabyteSymbol, StringComparison.Ordinal))
        return Megabytes.ToString(format, formatProvider);

    if (format.Contains(KilobyteSymbol, StringComparison.Ordinal))
        return Kilobytes.ToString(format, formatProvider);

    if (format.Contains(ByteSymbol, StringComparison.Ordinal))
        return Bytes.ToString(format, formatProvider);

    if (format.Contains(BitSymbol, StringComparison.Ordinal))
        return ((double)Bits).ToString(format, formatProvider);

    var (value, symbol) = GetLargestWholeNumber();
    return $"{value.ToString(format, formatProvider)} {symbol}";
}

